function validate(input) {
  const [{ cities = [] }] = input;
  const seen = new Set();
  for (const [state, city] of cities) {
    if (typeof state !== 'string' || !state || typeof city !== 'string' || !city) return 'Every row needs a state and a city.';
    const key = `${state.toLowerCase()}/${city.toLowerCase()}`;
    if (seen.has(key)) return `${city}, ${state} appears twice.`;
    seen.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const states = ['California', 'Texas', 'New York', 'Florida', 'Ohio', 'Oregon', 'Nevada', 'Maine'];
  const prefixes = ['San', 'Fort', 'New', 'Lake', 'Port', 'Mount', 'East', 'West', 'North', 'South', 'Glen', 'Rock'];
  const roots = ['Diego', 'Worth', 'Haven', 'Springs', 'Falls', 'Ridge', 'Bay', 'Vale', 'Field', 'Grove', 'Point', 'View', 'Mills', 'Creek', 'Harbor', 'Hill'];
  // Small cases reuse a short list, so names repeat across states and share prefixes.
  const shortList = ['Austin', 'Dallas', 'Houston', 'Albany', 'Buffalo', 'Salem', 'Portland', 'Springfield', 'San Diego', 'San Jose'];
  const rows = [], seen = new Set();
  const stateCount = small ? 1 + Math.floor(rand() * 3) : 8;
  const used = states.slice(0, stateCount);
  const target = small ? Math.floor(rand() * 9) : 1500;
  for (let tries = 0; rows.length < target && tries < target * 4; tries++) {
    const state = pick(used);
    const city = small ? pick(shortList) : `${pick(prefixes)} ${pick(roots)}${rand() < 0.5 ? '' : ` ${Math.floor(rand() * 9) + 1}`}`;
    const key = `${state}/${city}`;
    if (seen.has(key)) continue;
    seen.add(key);
    rows.push([state, city]);
  }
  return [{ cities: rows }];
}
